<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useControl, api } from '../stores/control'
import type { SwarmObject } from '../types'
const s=useControl()
const views=['Overview','Operations','Content Universe','Graph','Trends','Accounts','Synthesis','Experiments','Infrastructure','Audit & Replay']
const viewTypes:Record<string,string>={'Operations':'Task','Content Universe':'Candidate','Trends':'TrendCluster','Accounts':'Account','Synthesis':'Composition','Experiments':'Experiment','Infrastructure':'Worker'}
const inspectorTab=ref('Summary'), graphMode=ref('graph'), settingsOpen=ref(false), configText=ref(''), annotation=ref(''), replayInput=ref('')
const summary=ref<{objects:Record<string,number>;tasks:Record<string,number>;pending_outbox:number;last_sequence:number}|null>(null)
const queue=ref('ANALYZE_VIDEO'), newTitle=ref(''), newKind=ref('Account'), newMetadata=ref('{"topic":"nature","platform":"simulated"}')
const atoms=ref<SwarmObject[]>([]), storyboard=ref<string[]>([])
const editOpen=ref(false), editText=ref('')
function editObject(){if(!s.selected)return;editText.value=JSON.stringify({title:s.selected.title,metadata:s.selected.metadata,tags:s.selected.tags},null,2);editOpen.value=true}
async function saveObject(){try{await s.command('update',JSON.parse(editText.value));if(!s.error)editOpen.value=false}catch(e){s.error=String(e)}}
const renderKey=computed(()=>{const r=s.selected?.metadata.render as {key?:string}|undefined;return r?.key})
const isReplay=computed(()=>s.mode==='REPLAY')
const counts=computed(()=>summary.value?.objects||{})
const traceVisible=computed(()=>s.selected?s.trace:s.recent)
function select(o:SwarmObject){void s.select({objectId:o.id,objectType:o.object_type,version:o.version}).catch(e=>{s.error=String(e)})}
async function changeView(v:string){s.workspace=v;s.objectType=viewTypes[v]||'';await s.refresh()}
async function loadSummary(){summary.value=await api('/operations/summary')}
async function openSettings(){configText.value=JSON.stringify(s.configuration?.data,null,2);settingsOpen.value=true}
async function saveSettings(){try{await s.command('configure',JSON.parse(configText.value),true);if(!s.error)settingsOpen.value=false}catch(e){s.error=String(e)}}
async function loadAtoms(){if(!s.selected)return;atoms.value=await api('/candidates/'+s.selected.id+'/atoms');storyboard.value=atoms.value.map(a=>a.id)}
async function synthesize(){await s.command('synthesize',{atom_ids:storyboard.value});atoms.value=[];storyboard.value=[]}
function toggleAtom(id:string){storyboard.value=storyboard.value.includes(id)?storyboard.value.filter(x=>x!==id):[...storyboard.value,id]}
async function createObject(){try{await s.command('create',{object_type:newKind.value,title:newTitle.value,metadata:JSON.parse(newMetadata.value)})}catch(e){s.error=String(e)}}
function point(index:number){const count=Math.max(s.graph.nodes.length,1);const angle=index/count*Math.PI*2;return {x:330+Math.cos(angle)*230,y:230+Math.sin(angle)*170}}
function nodePoint(id:string){return point(s.graph.nodes.findIndex(n=>n.id===id))}
function keyboard(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.getElementById('swarm-search')?.focus()}}
let poll:ReturnType<typeof setInterval>
onMounted(async()=>{document.addEventListener('keydown',keyboard);try{await s.start();await loadSummary();poll=setInterval(()=>{void loadSummary().catch(()=>{})},3000)}catch(e){s.error=String(e)}})
onUnmounted(()=>{s.stop();clearInterval(poll);document.removeEventListener('keydown',keyboard)})
</script>
<template>
  <div class="swarm-shell">
    <header class="command-bar">
      <a class="brand" href="/swarm"><span class="brand-mark">M</span> MANU<span> / SWARM</span></a>
      <div class="command-search"><span>⌕</span><input id="swarm-search" v-model="s.search" placeholder="Search objects, sources, accounts…" @input="s.refresh()"><kbd>⌘ K</kbd></div>
      <span class="connection" :class="{online:s.connected}">● {{s.connected?'CONNECTED':'RECONNECTING'}}</span>
      <button class="mode" @click="s.setTime('')">{{s.mode}}</button><button @click="openSettings">Settings</button><a class="upstream" href="/chat">AI Manus ↗</a>
    </header>
    <nav class="nav-rail"><div class="section-label">COMMAND CENTER</div><button v-for="(v,i) in views" :key="v" :class="{active:s.workspace===v}" @click="changeView(v)"><span class="nav-number">{{String(i+1).padStart(2,'0')}}</span>{{v}}</button><div class="nav-footer"><span class="simulation-dot"></span> SIMULATION MODE<p>Real publishing disabled</p></div></nav>
    <aside class="context-panel">
      <div class="section-label">CONTEXT / FILTERS</div>
      <label>Object type<select v-model="s.objectType" @change="s.refresh()"><option value="">All objects</option><option v-for="t in s.configuration?.ontology.object_types" :key="t">{{t}}</option></select></label>
      <label>State<input v-model="s.status" placeholder="All states" @input="s.refresh()"></label>
      <div class="context-divider"></div><div class="section-label">QUICK ACTIONS</div>
      <button class="primary full" :disabled="s.busy||isReplay" @click="s.command('discover')">＋ Discover test video</button>
      <p class="muted">A reproducible source feeds the complete pipeline. Review and publishing stay under your control.</p>
      <div class="context-divider"></div><div class="section-label">QUEUE CONTROL</div>
      <select v-model="queue"><option v-for="q in s.configuration?.ontology.queues" :key="q">{{q}}</option></select>
      <div class="button-row"><button :disabled="isReplay" @click="s.command('pause_queue',{queue},true)">Pause</button><button :disabled="isReplay" @click="s.command('resume_queue',{queue},true)">Resume</button></div>
      <p class="muted">Paused: {{(s.configuration?.data.paused_queues as string[])?.join(', ')||'None'}}</p>
      <div class="context-divider"></div><div class="section-label">CREATE / EXTEND</div>
      <select v-model="newKind"><option>Account</option><option>Source</option><option>Experiment</option><option>SavedInvestigation</option><option>Alert</option></select>
      <input v-model="newTitle" placeholder="Object title"><textarea v-model="newMetadata" rows="5" aria-label="New object metadata"></textarea><button :disabled="!newTitle||isReplay" @click="createObject">Create object</button>
    </aside>
    <main class="workspace">
      <div v-if="s.error" class="error" role="alert">{{s.error}}<button @click="s.error=''">Dismiss</button></div>
      <div v-if="isReplay" class="replay-banner">HISTORICAL SNAPSHOT · {{s.cursor}} · Commands disabled</div>
      <div class="workspace-heading"><div><div class="eyebrow">OPERATIONAL INTELLIGENCE / {{s.workspace.toUpperCase()}}</div><h1>{{s.workspace==='Overview'?'Situation board':s.workspace}}</h1></div><span class="count">{{s.objects.length}} objects · bounded view</span></div>
      <section v-if="s.workspace==='Overview'" class="metrics-strip"><button v-for="kind in ['Candidate','Task','Account','Post']" :key="kind" @click="s.objectType=kind;s.refresh()"><span>{{kind}}s</span><strong>{{counts[kind]||0}}</strong><small>Inspect objects →</small></button></section>
      <section v-if="s.workspace==='Infrastructure'" class="system-summary"><h3>Runtime state</h3><p>{{summary?.pending_outbox||0}} pending outbox messages · event cursor {{summary?.last_sequence||0}}</p><pre>{{JSON.stringify(summary?.tasks,null,2)}}</pre><p class="muted">Worker concurrency and service lifecycle are managed in the launcher configuration.</p></section>
      <section v-if="s.workspace==='Graph'" class="graph-workspace">
        <div class="panel-heading"><h3>Explore around {{s.selected?.title||'a selected object'}}</h3><select v-model="graphMode"><option value="graph">Node graph</option><option value="matrix">Relation matrix</option><option value="table">Edge table</option></select></div>
        <p v-if="!s.primary" class="empty">Select an object in Content Universe, then open Graph.</p>
        <p v-if="s.graph.truncated" class="warning">Neighborhood truncated. Narrow the scope or use the relation matrix.</p>
        <svg v-if="graphMode==='graph'" viewBox="0 0 660 460" class="graph" aria-label="Selected object relationship graph">
          <line v-for="e in s.graph.edges" :key="e.id" :x1="nodePoint(e.from_object_id).x" :y1="nodePoint(e.from_object_id).y" :x2="nodePoint(e.to_object_id).x" :y2="nodePoint(e.to_object_id).y"/>
          <g v-for="(n,i) in s.graph.nodes" :key="n.id" :transform="`translate(${point(i).x},${point(i).y})`" tabindex="0" role="button" :aria-label="n.title" @click="select(n)" @keydown.enter="select(n)"><circle :r="n.id===s.primary?.objectId?12:7" :class="{selected:n.id===s.primary?.objectId}"/><text y="24" text-anchor="middle">{{n.object_type}}</text><title>{{n.title}}</title></g>
        </svg>
        <div v-else-if="graphMode==='matrix'" class="table-scroll"><p class="muted">Adjacency matrix · first 30 nodes. Select a row to inspect.</p><table class="object-table"><thead><tr><th>Object</th><th v-for="(n,i) in s.graph.nodes.slice(0,30)" :key="n.id" :title="n.title">{{i+1}}</th></tr></thead><tbody><tr v-for="(n,i) in s.graph.nodes.slice(0,30)" :key="n.id" @click="select(n)"><td>{{i+1}} {{n.title}}</td><td v-for="m in s.graph.nodes.slice(0,30)" :key="m.id" :title="s.graph.edges.filter(e=>e.from_object_id===n.id&&e.to_object_id===m.id).map(e=>e.edge_type).join(', ')">{{s.graph.edges.some(e=>e.from_object_id===n.id&&e.to_object_id===m.id)?'●':'·'}}</td></tr></tbody></table></div>
        <table v-else class="object-table"><thead><tr><th>From</th><th>Relationship</th><th>To</th></tr></thead><tbody><tr v-for="e in s.graph.edges" :key="e.id"><td>{{s.graph.nodes.find(n=>n.id===e.from_object_id)?.title}}</td><td><code>{{e.edge_type}}</code></td><td>{{s.graph.nodes.find(n=>n.id===e.to_object_id)?.title}}</td></tr></tbody></table>
      </section>
      <section v-else-if="s.workspace==='Audit & Replay'" class="event-list"><div class="panel-heading"><h3>Causal ledger</h3><span>{{traceVisible.length}} events</span></div><button v-for="e in traceVisible" :key="e.event_id" @click="replayInput=e.timestamp;s.setTime(e.timestamp)"><time>{{e.timestamp.slice(11,23)}}</time><code>{{e.event_type}}</code><span>{{e.object_id?.slice(0,8)}}</span><small>{{e.trace_id.slice(0,8)}}</small></button></section>
      <section v-else class="object-panel"><div class="panel-heading"><h3>{{s.objectType||'Swarm'}} registry</h3><span>LIVE STATE / CAUSAL OBJECTS</span></div><div class="table-scroll"><table class="object-table"><thead><tr><th>Object / identity</th><th>Type</th><th>Status</th><th>Revision</th><th>Updated</th></tr></thead><tbody><tr v-for="o in s.objects" :key="o.id" :class="{selected:o.id===s.primary?.objectId}" tabindex="0" @click="select(o)" @keydown.enter="select(o)"><td><strong>{{o.title}}</strong><code>{{o.id.slice(0,8)}}</code></td><td>{{o.object_type}}</td><td><span class="state" :class="o.status.toLowerCase()">{{o.status}}</span></td><td>v{{o.version}}</td><td class="mono">{{o.updated_at.slice(11,19)}}</td></tr></tbody></table></div><div v-if="!s.objects.length" class="empty"><h3>No objects in this view</h3><p>Discover a test video or adjust your filters to begin.</p></div></section>
      <section v-if="s.workspace==='Overview'" class="event-list compact"><div class="panel-heading"><h3>Activity stream</h3><span>SEQUENCE {{s.lastSequence}}</span></div><div v-for="e in s.recent.slice(0,8)" :key="e.event_id" class="activity"><time>{{e.timestamp.slice(11,19)}}</time><code>{{e.event_type}}</code><span>{{e.object_id?.slice(0,8)}}</span></div></section>
    </main>
    <aside class="inspector" data-testid="object-inspector"><div class="section-label">OBJECT INSPECTOR</div><template v-if="s.selected"><span class="object-kind">{{s.selected.object_type}}</span><h2>{{s.selected.title}}</h2><code class="object-id">{{s.selected.id}}</code><span class="state">{{s.selected.status}} · v{{s.selected.version}}</span><div class="inspector-tabs"><button v-for="t in ['Summary','Links','Timeline','Provenance','Raw']" :key="t" :class="{active:inspectorTab===t}" @click="inspectorTab=t">{{t}}</button></div>
      <div v-if="inspectorTab==='Summary'">
        <dl><dt>Created</dt><dd>{{s.selected.created_at}}</dd><dt>Updated</dt><dd>{{s.selected.updated_at}}</dd><dt>Route score</dt><dd>{{s.selected.metadata.route_score??'—'}}</dd><dt>Provider / mode</dt><dd>{{s.selected.metadata.adapter||'Simulated fixture'}}</dd></dl>
        <video v-if="renderKey" :src="'/api/v1/swarm/media/'+renderKey" controls preload="metadata"></video>
        <div class="inspector-actions"><button :disabled="isReplay" @click="editObject">Edit object configuration</button><button @click="changeView('Graph')">Explore Around ↗</button><button @click="changeView('Audit & Replay')">Replay Trace ↗</button>
          <button v-if="s.selected.object_type==='Candidate'" :disabled="isReplay" @click="loadAtoms">Build storyboard</button>
          <template v-if="s.selected.object_type==='Composition'"><button v-if="s.selected.status==='REVIEW'" class="primary" :disabled="isReplay" @click="s.command('approve')">Approve composition</button><button v-if="s.selected.status==='REVIEW'" :disabled="isReplay" @click="s.command('reject')">Reject composition</button><button v-if="s.selected.status==='APPROVED'" class="primary" :disabled="isReplay" @click="s.command('publish')">Publish simulated post</button></template>
          <template v-if="s.selected.object_type==='Account'"><button :disabled="isReplay" @click="s.command(s.selected.status==='PAUSED'?'resume_account':'pause_account')">{{s.selected.status==='PAUSED'?'Resume':'Pause'}} account</button></template>
          <button v-if="s.selected.object_type==='Task'&&!['SUCCEEDED','CANCELLED','DEAD_LETTER'].includes(s.selected.status)" :disabled="isReplay" @click="s.command('cancel_task')">Cancel task</button>
        </div>
        <div v-if="atoms.length" class="storyboard"><h3>Storyboard · select in play order</h3><button v-for="a in atoms" :key="a.id" :class="{active:storyboard.includes(a.id)}" @click="toggleAtom(a.id)">{{storyboard.indexOf(a.id)+1||'—'}} {{a.metadata.motif}} · {{a.metadata.start}}–{{a.metadata.end}}s</button><button class="primary" :disabled="!storyboard.length||isReplay" @click="synthesize">Render storyboard</button></div>
        <textarea v-model="annotation" rows="3" placeholder="Add an observation…"></textarea><button :disabled="!annotation||isReplay" @click="s.command('annotate',{body:annotation});annotation=''">Save annotation</button>
      </div>
      <div v-else-if="inspectorTab==='Links'"><button v-for="n in s.graph.nodes.filter(n=>n.id!==s.selected?.id)" :key="n.id" class="link-object" @click="select(n)"><small>{{n.object_type}}</small>{{n.title}}</button></div>
      <div v-else-if="inspectorTab==='Timeline'" class="mini-timeline"><button v-for="e in s.timeline" :key="e.event_id" @click="s.setTime(e.timestamp)"><small>{{e.timestamp.slice(11,19)}}</small>{{e.event_type}}</button></div>
      <div v-else-if="inspectorTab==='Provenance'"><h3>{{s.selected.metadata.provenance_status||'See causal trace'}}</h3><p class="muted">Unknown media remains available for intelligence and synthesis. This build renders synthetic fixture material and publishes only simulated posts.</p><button @click="changeView('Audit & Replay')">Inspect full lineage</button></div>
      <pre v-else>{{JSON.stringify(s.selected,null,2)}}</pre>
    </template><div v-else class="empty">Select an object to inspect its state, relationships and causal history.</div></aside>
    <footer class="time-rail" data-testid="time-rail"><strong>{{s.mode}}</strong><span>{{s.selected?.title||'Global event context'}}</span><div class="event-ticks"><button v-for="e in s.timeline.slice(-40)" :key="e.event_id" :title="e.event_type+' '+e.timestamp" @click="s.setTime(e.timestamp)"></button></div><input v-model="replayInput" placeholder="ISO timestamp" aria-label="Replay timestamp"><button @click="s.setTime(replayInput)">Replay</button><button @click="s.setTime('')">Go live</button></footer>
    <div v-if="editOpen" class="settings-backdrop"><section class="settings-dialog"><div class="panel-heading"><h2>Edit {{s.selected?.object_type}}</h2><button @click="editOpen=false">Close</button></div><p>Changes are version-checked and recorded in the causal ledger. Secrets must use references.</p><textarea v-model="editText" aria-label="Object configuration" rows="20"></textarea><button class="primary" :disabled="isReplay||s.busy" @click="saveObject">Save object</button></section></div>
    <div v-if="settingsOpen" class="settings-backdrop"><section class="settings-dialog"><div class="panel-heading"><h2>Swarm configuration</h2><button @click="settingsOpen=false">Close</button></div><p>Versioned, audited controls for scoring, providers, retries, media limits and queue policy.</p><textarea v-model="configText" aria-label="Swarm configuration" rows="22"></textarea><div class="button-row"><button class="primary" :disabled="isReplay||s.busy" @click="saveSettings">Apply configuration</button><span>Revision {{s.configuration?.version}}</span></div></section></div>
  </div>
</template>
<style scoped>
.swarm-shell{--bg:#0d1219;--panel:#121a24;--border:#283441;--muted:#8092a6;--cyan:#6bd8ee;color:#dce5ef;background:var(--bg);font:12px/1.5 Inter,Arial,sans-serif;display:grid;grid-template-columns:170px 210px minmax(380px,1fr) 310px;grid-template-rows:64px minmax(0,1fr) 64px;height:100vh;min-width:1080px;font-variant-numeric:tabular-nums}*{box-sizing:border-box}button,input,select,textarea{font:inherit}button{cursor:pointer;background:#1b2734;border:1px solid #334454;color:#cbd9e6;border-radius:4px;padding:7px 10px}button:hover{background:#273b4e;border-color:#6bd8ee}button:disabled{opacity:.4;cursor:not-allowed}input,select,textarea{background:#0d151e;border:1px solid #2e3d4b;color:#dce5ef;border-radius:4px;padding:8px;width:100%;outline:none}input:focus,textarea:focus{border-color:var(--cyan)}a{color:inherit;text-decoration:none}.command-bar{grid-column:1/-1;display:flex;align-items:center;gap:18px;padding:0 22px;border-bottom:1px solid var(--border);background:#141d27}.brand{font-weight:800;font-size:15px;white-space:nowrap;letter-spacing:1px}.brand>span:last-child{color:#94a7b9;font-weight:400}.brand-mark{display:inline-grid;place-items:center;width:30px;height:30px;border:1px solid var(--cyan);margin-right:10px;color:var(--cyan)}.command-search{display:flex;align-items:center;gap:8px;max-width:520px;flex:1;background:#0d151e;border:1px solid var(--border);border-radius:4px;padding:0 10px}.command-search input{border:0}.command-search kbd{color:var(--muted);white-space:nowrap}.connection{font:10px monospace;color:#d99c55;letter-spacing:1px}.connection.online{color:#71c9a5}.mode{color:var(--cyan)}.upstream{color:#91a8bd;font-size:11px}.nav-rail{border-right:1px solid var(--border);padding:22px 10px;display:flex;flex-direction:column;background:#111923}.section-label{font-size:9px;letter-spacing:1.5px;font-weight:700;color:#859aaf;margin-bottom:15px}.nav-rail .section-label{padding-left:8px}.nav-rail>button{background:none;border-color:transparent;text-align:left;